import { HelpBody } from './helpContent';

/**
 * The help catalog in German.
 *
 * <p>A file per language: a translation pass is then reviewable on its own, and eighteen articles
 * in five languages inline would be one literal nobody could edit without breaking a quote. A key
 * that is missing here falls back to the English body, visibly — see `bodyFor`.</p>
 */
export const DE: Readonly<Record<string, HelpBody>> = {
  "phrases": {
    title: "Phrases: die Sätze, die Sie nicht mehr abtippen",
    whatItIs: "Eine Liste von Sätzen, die Sie aufbewahren — als Schaltflächen im Abschnitt **Phrases** des Panels. Eine davon drücken, und sie liegt in der Zwischenablage; eingefügt wird sie dort, wo Sie sie sonst getippt hätten, meist im Eingabefeld von Claude Code. Bearbeitet wird die Liste in einem eigenen Tab: **ConnectOtherAIs: Edit phrases**.",
    why: "Manche Anweisungen tippt man mehrmals am Tag — *mach einen Pull Request, nimm ihn an, deploye, prüf dass es läuft*. Sie erneut zu tippen ist keine Arbeit, sondern Reibung, und ein aus dem Gedächtnis wiederholter Satz verändert sich jedes Mal ein wenig.\n\n**Es wird kopiert und nicht für Sie ins Feld geschrieben, und das war eine Entscheidung, keine Abkürzung.** Claude Code hat keinen Befehl, der beliebigen Text annimmt: der eine, der einen Prompt annimmt, füllt nur eine NEUE Unterhaltung, nie die, in der Sie gerade sind. Übrig blieb ein synthetischer Tastendruck über die Windows-API — nur Windows, etwa eine Sekunde lang, und in diese Richtung nie gemessen. Ein `Ctrl+V` ist der bessere Preis als ein Mechanismus, der auf einem fremden Rechner stillschweigend scheitern kann.",
    setup: "**Edit phrases** aus dem Abschnitt *Phrases* des Panels oder aus der Befehlspalette. **Add a phrase** drücken, einen Namen für die Schaltfläche vergeben und den Satz in das große Feld schreiben. Alles wird kurz nach dem letzten Tastendruck gespeichert.\n\nDer Name ist nur eine Beschriftung; in die Zwischenablage geht der Satz selbst. Lassen Sie den Namen leer, trägt die Schaltfläche die erste Zeile des Satzes.",
    usage: "Der Abschnitt **Phrases** zeigt eine Schaltfläche je Satz. Drücken, einfügen, weiterarbeiten. Die Liste gehört Ihnen allein: Sie geht nie an `coai-mcp` und nie an einen Team server, und sie ist bei eingeschaltetem *This side* auf beiden Seiten dieselbe — ein Satz, den Sie geschrieben haben, ist keine Eigenschaft des Rechners, auf dem Sie ihn geschrieben haben.\n\nEin Satz wird genau so gespeichert, wie Sie ihn geschrieben haben, mit Leerzeichen und Zeilenumbrüchen: ein eingerückter Schnipsel wird eingerückt eingefügt.",
    whatCanGoWrong: "**Eine Zeile ohne Text wird verworfen.** Der Name ist die Beschriftung, der Text ist die Sache — eine Zeile ohne Inhalt ist kein Satz. Eine Zeile, die Sie in `settings.json` vertippt haben, wird für sich verworfen, und der Rest der Liste funktioniert weiter: alle Sätze wegen eines falschen zu verlieren wäre das schlimmere Versagen.\n\n**Ein Speichern, das nicht gelingt, sagt es — und sagt warum.** Der Tab behält das Getippte und zeigt den Grund der Ablehnung in den Worten dessen, der sie ausgesprochen hat, statt die Liste ohne Ihre Worte neu zu zeichnen. Der häufigste Grund ist ein Fenster, das einer Aktualisierung nicht gefolgt ist: VS Code kennt weiterhin nur die Einstellungen, die es beim Öffnen des Fensters registriert hat, ein Satz lässt sich also erst nach dem Neuladen speichern — die Zeile sagt genau das, mit der Schaltfläche dafür.\n\n**Nichts wird für Sie gedrückt.** Der Satz erreicht die Zwischenablage und hört dort auf; ihn einzufügen und abzuschicken bleibt Ihre Sache.",
  },
  "notifications": {
    title: "Notifications: alles, was die Erweiterung Ihnen gesagt hat",
    whatItIs: "Eine Seite mit allen Meldungen, die ConnectOtherAIs auf Ihrem Bildschirm gezeigt hat, aufbewahrt nachdem die Einblendung verschwunden ist: was sie sagte, wann, woher, was zu tun ist und wie oft es passiert ist. Der Abschnitt **Notifications** im Panel nennt die Zahl der neuen und öffnet sie.",
    why: "Eine Meldung, die Sie nicht angesehen haben, ist eine Meldung, die nie stattgefunden hat. Am 16.09.2026 wurde eine um 19:05 gelöschte Rolle noch elf Runden lang mitgeprüft, weil der Einstellungsspiegel um 18:27 angehalten hatte und das genau einmal sagte — in einer Einblendung, die niemand sah. Neunzig Minuten eines Arbeitstags gingen dafür drauf, das herauszufinden. Jetzt geht jede Meldung zuerst in eine Datei und erst dann auf den Bildschirm, damit die Antwort auf «was stand da?» woanders liegt als im Gedächtnis eines Menschen.",
    setup: "Nichts einzurichten. Beide Hälften schreiben, während sie sprechen: diese Erweiterung in `notifications.jsonl`, der MCP-Server daneben in `server-notices.jsonl`, im selben Datenordner wie alles andere. Wird der Ordner verschoben, ziehen sie mit um.",
    usage: "Der Abschnitt **Notifications** sagt, wie viel seit Ihrem letzten Blick neu ist, und öffnet die Seite. Dort ein Reiter je ART — ein Fehlschlag, eine Ablehnung, ein Anhalten, ein Sturm, eine Frage, die Sie beantwortet haben — und eine Zeile je Vorfall, so oft er auch aufgetreten ist.\n\n**Eine Zeile ist ein Fehler, kein einzelnes Auftreten.** Ging etwas vierhundertmal schief, ist das eine Zeile mit der Vierhundert und daneben, wie schnell sie eintrafen. Sortieren nach jeder Spalte; Leerwerte stehen in beiden Richtungen hinten, damit eine nicht messbare Rate nie nach oben rutscht. Die Suche findet jedes Wort der Zeile, auch die Meldung selbst.\n\nDas Öffnen der Seite markiert die geladenen Einträge als gelesen. **Bei gesetztem Filter markiert sie nichts** — drei Zeilen auf dem Bildschirm dürfen nicht behaupten, dreitausend seien gelesen — und die Zeile über der Tabelle sagt, welches von beiden gerade gilt. **Mark everything read** ist die Schaltfläche für eine Historie, die Sie nicht rückwärts durchgehen wollen.",
    whatCanGoWrong: "**Ein sich wiederholender Fehler ist begrenzt und sagt das, statt so zu tun als ob.** Dieselbe Sache kann in einem Fensterlauf tausendmal festgehalten werden; danach hört die Datei auf, und die Zeile liest sich *1000+* — nie als Zahl, die niemand kennen kann. Drei Fenster, die das je erreichen, erscheinen als *1000+ in each of 3 runs*, denn drei Fenster in Not sind nicht ein dreifach so großer Vorfall.\n\n**Die Seite zeigt die neuesten paar tausend Einträge, nicht die Datei.** Gibt es ältere, sagt sie das, und die bleiben ungelesen, bis Sie hingehen oder **Mark everything read** drücken.\n\n**Eine Zählung, die nicht gelesen werden konnte, sagt das, statt null zu zeigen.** «Es wurde noch nichts aufgeschrieben», «die Benachrichtigungen konnten nicht gelesen werden» und «nichts Neues» sind absichtlich drei verschiedene Sätze: ein kaputter Lesevorgang, der als sauberes Null erscheint, bringt einen Menschen dazu, einem Zähler nicht mehr zu trauen — und dieser Zähler gibt es, weil jemandem eine Meldung entgangen ist.\n\n**Geheimnisse werden beim Hineinschreiben entfernt.** Ein Passwort, ein Token oder ein Schlüssel in einer URL oder in einem Fehlertext wird ersetzt, bevor die Zeile die Datei erreicht; alles andere bleibt erhalten. Auf einer Maschine kann es zwei Datenordner geben, einen für Windows und einen für WSL; die Seite nennt den, den sie liest, denn «er ist leer» und «Sie sehen in den anderen» sind verschiedene Probleme.",
  },
  "your-own-roles": {
    title: "Eigene Rollen: prüfen, was kein Code ist",
    whatItIs: "Eine Review-Rolle ist ein Prüfer mit einer Frage. Fünf liefert dieses Produkt mit: Plankritik, Konventionen, Architektur, Sicherheit und Zuverlässigkeit, Performance und UX-DX. **Die Rollen, die Sie hinzufügen, gehören Ihnen** — mit Namen in Ihrer Sprache und den Fragen, die Sie gestellt haben wollen.\n\nDas Gate ringsherum ändert sich nicht. Dieselben Runden, dieselbe Schwelle, dieselben Funde mit denselben Kategorien, dasselbe Urteil. Was sich ändert, ist, wonach ein Prüfer gefragt wird — und das ist der Prompt, den Sie schreiben.",
    why: "Die fünf mitgelieferten sind die fünf, die ein Programmierer will. Wer Anforderungen gegen eine Spezifikation prüft, Bewerbungen liest oder eine Produktbeschreibung vor der Veröffentlichung durchgeht, braucht eine andere Frage — und niemand kann sie alle im Voraus kennen. Deshalb ist es eine Liste, die Sie bearbeiten, und keine, die wir ausliefern.",
    setup: "**Edit roles…** im Abschnitt *Prompts per round* öffnet die Rollenseite. Legen Sie eine Rolle an, geben Sie ihr einen Namen und schreiben Sie ihren allgemeinen Prompt — die Frage, die gestellt wird, wenn nichts anderes gewählt ist. Weitere Prompts für engere Fragen kommen dazu; in *Prompts per round* wird pro Runde einer davon angeboten.\n\nDie fünf mitgelieferten Rollen stehen auf derselben Seite. Den Text jedes ihrer Prompts können Sie neu schreiben und eigene Prompts hinzufügen; umbenennen, auf die andere Stufe verschieben oder Mitgeliefertes löschen können Sie sie nicht — ihre Namen sind bereits Schlüssel in Ihren Einstellungen, in offenen Sitzungen und in jeder aufgezeichneten Runde, und der Review-Server liest nichts davon aus Ihrer Konfiguration: eine Seite, die das ändern ließe, zeigte etwas, das keine Runde je tut.\n\n**Eine Kennung wird für Sie erzeugt** und unter dem Namen angezeigt. So heißt Ihre Rolle in der Einstellung, in der Sitzungsdatei und in der Datenbank, deshalb ändert sie sich danach nicht mehr — benennen Sie die Rolle um, so oft Sie wollen.\n\n**Höchstens fünf Rollen sind pro Stufe aktiv.** Eine sechste lässt sich nicht anhaken; schalten Sie zuerst eine ab. Eine Rolle, die Sie anlegen, während bereits fünf aktiv sind, entsteht abgeschaltet — was die Seite zeigt, ist damit das, was läuft. Eine abgeschaltete Rolle bleibt mit allem, was Sie hineingeschrieben haben, auf dieser Seite.",
    usage: "Alles auf der Seite speichert sich einen Moment, nachdem Sie aufgehört haben zu tippen. Der TEXT eines Prompts landet in einer Datei neben Ihren übrigen coai-Daten — genau dort hat der Server Prompt-Überschreibungen schon immer gelesen. Ein neu geschriebener Prompt übersteht daher ein Update, und das Löschen der Datei stellt das Mitgelieferte wieder her.\n\n**Eine Rolle für etwas, das keine Programmieraufgabe ist,** wird gespeichert und angezeigt und nimmt noch an keiner Runde teil: die Stufe, die ein Dokument statt eines Diffs prüft, entsteht gerade erst. Die Seite sagt das an der Rolle.\n\n**Das Entfernen einer Rolle fragt vorher nach** und nimmt die Prompts mit, die Sie darin geschrieben haben: die Zeile lässt sich neu tippen, die Absätze darunter nicht.",
    whatCanGoWrong: "**Ein `coai-mcp` älter als 0.19.0 liest Ihre Rollen gar nicht.** Dieses Release hat es gelernt: darunter stehen die Rollen im Panel und in keiner Runde — nichts schlägt fehl und nichts sagt es, weshalb die Seite eine Warnung mit Ihrer Version zeigt. Aktualisieren Sie den Server unter **MCP server**.\n\n**Ein Team server führt die Rollen aus, die sein Betreiber eingerichtet hat.** Er bringt dieselben fünf mit, und sein Betreiber kann weitere hinzufügen: `Coai:ExtraRoles` auf dem Server, oder `Coai:AllowAnyRole`, um jede GÜLTIGE Rollenkennung anzunehmen. Das Panel fragt jeden eingerichteten Server, welche Rollen er ausführt, und sagt es neben der Rolle — VOR einer Runde, nicht in ihrem Ergebnis. Ein Server, der zu alt ist, um danach gefragt zu werden, oder einer, der nicht erreichbar war, führt weiterhin die fünf mitgelieferten aus — und der Satz sagt, welcher der beiden Fälle eintrat, denn der eine wird durch ein Server-Update behoben und der andere durch einen Blick aufs Netz.\n\n**Zwei Seiten, zwei Rollensätze.** Mit *This side* gehören Ihre Rollen der Seite, auf der Sie arbeiten, wie Runden und Schwellen. Die Prompt-Dateien nicht: eine Frage, die Sie geschrieben haben, ist eine Frage, wo immer Sie sie stellen.",
  },
  "chat-with-other-ai": {
    title: "Chat with other AI: ein zweites Modell zu einer Stelle befragen",
    whatItIs: "Markieren Sie einen Absatz in der Antwort Ihres Assistenten und drücken Sie `Ctrl+Alt+A` — es öffnet sich ein Tab, in dem das Modell eines anderen Anbieters ihn in Ihrer Sprache erklärt, und das Gespräch geht weiter. Im Kontextmenü steht dasselbe als zwei Einträge, und jeder sagt, was er tut: **CoAI: default** fragt sofort das als main markierte Modell, und **CoAI: choose** legt den Zug ins Eingabefeld — Sie können Modell oder Prompt noch ändern und selbst Enter drücken. Die Tasten folgen weiterhin der Einstellung **When to send**, die ein Menüeintrag nicht zeigen kann.\n\nEs geht auch in einer gewöhnlichen Datei — `.md`, `.cs`, jeder, die Sie öffnen können. Markieren Sie eine Stelle und drücken Sie dieselben Tasten, oder klicken Sie mit der rechten Maustaste. Dort wird die Markierung direkt aus dem Editor gelesen statt über die Zwischenablage kopiert: sofort, und Ihre Zwischenablage bleibt unangetastet. Ohne Markierung geht die ganze Datei, und bei einer großen Datei wird vorher gefragt. Das Gespräch trägt den Namen der Datei, und eine zweite Frage zu derselben Datei führt dasselbe Gespräch fort.\n\n**CoAI: take the question** ist dasselbe für eine Frage, die Claude Code IHNEN stellt. Sein Fragefenster lässt sich nicht markieren, es gibt nichts zu kopieren — also wird die Frage aus der Sitzungsdatei gelesen, mit jeder Option und jeder Beschreibung, und landet im Eingabefeld. Es lehnt ab, statt zu raten: War die letzte Frage schon beantwortet, sagt es das; warten zwei Sitzungen in diesem Ordner, nennt es das, statt eine auszuwählen.",
    why: "Eine dichte englische Antwort ist nicht immer eine klare, und dasselbe Modell um eine Erklärung zu bitten liefert dieselben Worte. Ein anderer Anbieter liest sie unvoreingenommen. Von Hand sind das fünf Schritte — markieren, kopieren, in den Browser wechseln, neuer Chat, einfügen — mehrmals pro Stunde; hier ist es ein Tastendruck, und die Antwort bleibt im Editor.",
    setup: "Nichts, sofern bereits ein Reviewer auf der Laufzeit `antigravity` aktiv ist — der beantwortet einen Chat, und genommen wird der erste, der es kann, sofern Sie keinen anderen nennen. Vier Einstellungen gehören Ihnen: der Prompt, mit dem die Stelle reist (standardmäßig das eine Wort `Explain`), die Antwortsprache (standardmäßig Englisch und bewusst nicht die Sprache dieser Seiten), mit welchem Modell ein neuer Tab ÖFFNET, und ob sofort gesendet wird. Das Modell ist nicht mehr nur eine Einstellung: der Tab hat eine eigene Auswahl, und was Sie dort wählen, gehört diesem Gespräch und nicht allen künftigen. **CoAI: add the question** ist derselbe Leser mit dem anderen Verb: Die Frage wird an das angehängt, was im Eingabefeld schon steht, statt es zu ersetzen — der eben verfasste Beitrag behält seine Anweisung und bekommt die Frage darunter als weiteres Material.\n\n**Edit chat presets** öffnet einen Tab mit beiden Listen, und alles darin speichert beim Tippen. Seit es Presets gibt, ist jener eine Prompt **Ihre gespeicherten Prompts, jeder mit einem Namen** — einer davon als Hauptprompt angehakt, und genau der reist mit, wenn eine Erfassung von selbst sendet. Daneben stehen **Ihre gespeicherten Modelle, jedes mit einem Namen** und wahlweise einem Prompt, mit dem das Eingabefeld öffnet. Was immer im alten einzelnen Prompt stand, wurde beim ersten Lesen dieser Version zu Ihrem ersten benannten Preset — nichts davon ging verloren.\n\n**In der Seitenleiste ist *What to ask about the selection* jetzt eine Auswahl.** Sie nennt Ihre gespeicherten Prompts, statt eine Kopie davon zu halten, und **Edit presets…** daneben öffnet den Tab, in dem die Worte selbst bearbeitet werden — die beiden können nun nicht mehr auseinanderlaufen. Leer bedeutet den als Haupt markierten Prompt. *Which model answers* stellt dieselben zwei Fragen wie der Tab: erst den Anbieter, dann eines seiner Modelle — und ein leeres zweites Feld bedeutet das Modell, auf das die Reviewer-Zeile selbst eingestellt ist.",
    usage: "Die Tastenkombination kopiert die Auswahl selbst und tut dann, was Ihre Einstellung **When to send** sagt: sofort fragen oder den Beitrag im Eingabefeld lassen. Die beiden Kontextmenü-Einträge fragen sie nicht — jeder sagt in seinem eigenen Namen, was er tun wird. Kopieren kann das Menü ebenfalls nicht: Das Schließen des Menüs nimmt die Auswahl aus dem Panel, also nimmt es das zuletzt Kopierte. Deshalb steht die Stelle oben im Tab: Sie sehen, was gleich gefragt wird. Ein Tab pro Assistenten-Sitzung, damit sich zwei Gespräche nie mischen.\n\n**Das Eingabefeld bleibt, wo es ist**, und das Gespräch scrollt darüber. Zu einer neuen Antwort wird nur gesprungen, wenn Sie ohnehin unten waren: scrollen Sie zum Lesen nach oben, zieht Sie nichts weg, und **Jump to newest ↓** bringt Sie zurück, wenn Sie wollen. Das Feld wächst beim Tippen bis etwa auf ein Drittel des Fensters und scrollt erst dann. Enter sendet, Shift+Enter ist eine neue Zeile, und es gibt eine **Send**-Schaltfläche für alle, die lieber drücken. Daneben **leert ✕ das Feld** mit einem Druck, und jede ± Steuerung darüber trägt jetzt ein Zeichen — eine Lupe für die Schriftgröße, eine Sonne für den Ton —, damit vier gleich aussehende Schaltflächen nebeneinander keine Reihenfolge mehr sind, die man sich merken muss.\n\n**Antworten werden gesetzt, nicht ausgekippt** — Überschriften, nummerierte und Aufzählungslisten, Tabellen, Code. Links sind blau, und was sie öffnen, ist begrenzt: ein Pfad INNERHALB dieses Arbeitsbereichs öffnet die Datei im Editor, eine `http`- oder `https`-Adresse den Browser; alles andere bleibt Text — ein Pfad, der den Arbeitsbereich verlässt, eine `file://`-URL und eine Adresse, die ein Modell bloß im Satz erwähnt und nicht als Link geschrieben hat. Eine Datei, die nicht gefunden wird, sagt das, statt nichts zu tun. Ihre eigenen Worte stehen rechts, eine Antwort trägt eine Beschriftung mit dem Modell, das sie gab, in dessen Farbe, und eine Linie schließt sie ab — das Ende einer langen Antwort ist damit auffindbar. **Copy answer** gibt Ihnen die ganze Antwort als Markdown, und **Copy block** — unter jedem Codeblock und jedem Zitat — nur diesen einen. Endet ein Modell mit einer Antwort, die es Ihnen zum Weitersenden vorschlägt, und öffnet sie als ```reply-Block, so liest sich dessen Schaltfläche als **Copy the reply prompt**. Allein dieses Kennzeichen erkennt die Erweiterung: dass ein Modell es schreibt, bewirkt Ihr eigener Prompt und nichts, was hinter Ihrem Rücken hinzugefügt wird.\n\n**Die Auswahl fragt erst nach dem Anbieter, dann nach einem seiner Modelle**, denn eine Modellliste gehört einem Anbieter. Mitten im Gespräch zu wechseln ist vorgesehen — der ganze Verlauf geht mit —, und neben der Auswahl steht, was dieses Gespräch bisher gekostet hat. Über dem Feld liegen zwei Reihen Presets: Ihre Modelle in der Farbe ihres Anbieters, derselben, die dieser Anbieter überall sonst hier trägt, und Ihre Prompts in einer Farbe, die kein Anbieter hat — ein Prompt darf nie für einen Anbieter gehalten werden. **Eine Schaltfläche leuchtet nur, solange ihre Worte die geltende Anweisung sind.** Wählen Sie ein Modell von Hand in den beiden Listen, oder löschen Sie die Anweisung aus dem Feld, dann erlischt die Schaltfläche, die sie dort hingeschrieben hat — die Rolle, die eine Modellvorlage hinzufügt, zählt genauso, weshalb das Leeren des Feldes beide erlöschen lässt.\n\n**Ein leeres Feld mit einem anderen gewählten Modell ist ein Nachfragen**: dieselbe Frage geht an das andere Modell und nimmt das Gespräch ohne die Antwort mit, die Sie nicht wollten; die Schaltfläche sagt vorher, wer dran ist. **Fügen Sie einen Screenshot ein**, und er geht mit der nächsten Frage. **Stop** erscheint, während ein Zug läuft, und beendet genau den Zug, für den es gezeichnet wurde, nie den nächsten.\n\n**Asked** steht oben rechts neben den ±-Reglern und zeigt, was SIE in der Claude-Code-Sitzung geschrieben haben, aus der dieser Tab stammt. Nach ein paar Stunden ist die Frage, mit der die Arbeit begann, nach oben aus dem Bild gelaufen, und das Fenster kann nicht mehr sagen, worum es geht — man fragt dann den Assistenten, woran er gerade arbeitet. Die Worte sind nie verschwunden: Dies liest sie aus der Sitzungsdatei, die über den eigenen Titel diesem Tab zugeordnet wird, damit zwei Sitzungen in einem Ordner nie verwechselt werden, und heftet sie über das Gespräch, wo kein Scrollen sie erreicht. `‹` und `›` blättern durch jeden Ihrer Beiträge, den ältesten zuerst. Noch einmal gedrückt klappt es wieder zu — in einer halben Sekunde, nicht ruckartig. Ein aus einer Datei geöffneter Tab hat keine Sitzung hinter sich und deshalb auch keine Schaltfläche.\n\n**Carry nothing above** steht an der letzten Antwort. Ein Druck zeichnet darunter eine strichpunktierte orange Linie: Von da an bekommen ein Modell, zu dem Sie wechseln, und ein Team-Server — dem die ganze Unterhaltung bei JEDEM Beitrag übergeben wird — nur noch, was unterhalb der Linie steht. Gelöscht wird nichts: Das Gespräch bleibt vollständig stehen und lässt sich scrollen und kopieren wie zuvor.\n\nEs heißt nicht „vergiss das“, sondern „trag das nicht weiter“: Das lokale Modell, mit dem Sie sprechen, hält die Unterhaltung im eigenen Prozess und behält jedes Wort. Gespart wird bei den anderen beiden — bei einem Wechsel, der sonst zehn Beiträge zu einem Thema an ein Modell wirft, das Sie zu einem anderen fragen, und bei einem Team-Server, der Ihnen diese zehn Beiträge unter jeder weiteren Frage berechnet.\n\nNoch einmal weiter unten gedrückt, wandert der Punkt dorthin. Rückgängig zu machen gibt es nichts: Die Marke ist eine Position, kein Zustand, und gezeichnet wird immer nur die aktuelle. Sie übersteht ein Neuladen des Fensters zusammen mit dem Gespräch.\n\n**CoAI: switch conversations…** ist die Liste aller Gespräche. `Ctrl+Shift+Alt+G` (`Cmd+Shift+Alt+G` auf dem Mac), das Kontextmenü oder die Befehlspalette. Oben **Open** — was in diesem Fenster gerade in einem Tab steht, mit dem Modell, der Zahl der Beiträge und dem zuletzt Gesagten; darunter **Recent** — alles andere, das Neueste zuerst. Tippen filtert nach dem Titel, nach dem Modell, das geantwortet hat, und nach eben dieser letzten Zeile: ein Gespräch, an das Sie sich über ein einziges Wort seiner Antwort erinnern, ist ein Wort entfernt. Ein offenes wird nach vorn geholt. Ein geschlossenes wird dort wieder geöffnet, wo es aufgehört hat — der ganze Verlauf, nichts läuft, bis Sie fragen, und genau diese erste Frage trägt das Gespräch zu dem Modell hinüber, das sie beantwortet.\n\n**Ein Papierkorb auf jeder geschlossenen Zeile** vergisst dieses Gespräch, und `Alt+Entf` (`Cmd+Entf` auf dem Mac) vergisst das Gespräch unter dem Cursor. Die Liste bleibt in beiden Fällen offen: fünf aufzuräumen sind fünf Tastendrücke und nicht fünf Mal Öffnen. Ein offenes Gespräch hat keinen Papierkorb — schließen Sie erst seinen Tab. **Die Weltkugel im Titel** weitet die Liste von diesem Ordner auf alle Ordner und zurück, und der Titel sagt immer, welches von beiden Sie gerade sehen.\n\n**Vergessen ist nicht Vernichten.** Die Zeile verschwindet sofort und taucht in keiner Liste wieder auf, das Gespräch selbst wird aber auf der Festplatte beiseitegelegt und erst nach denselben neunzig Tagen wie alles andere wirklich gelöscht — ein Tastendruck auf die falsche Zeile kostet Sie also kein Gespräch.\n\n**CoAI: go to conversation** ist der umgekehrte Weg und meist der, den man will. `Ctrl+Alt+G` (`Cmd+Alt+G` auf dem Mac), das Kontextmenü oder die Palette — gedrückt in dem Tab, in dem Sie arbeiten, nicht in einer Liste. Ist das Gespräch in diesem Fenster schon offen, kommt es nach vorn. Ist es nur gespeichert, öffnet es sich wieder und wird an diesen Tab gebunden, sodass jeder weitere Druck an derselben Stelle landet. Ist für den Tab nichts gespeichert, öffnet sich die Liste mit **New conversation** unter dem Cursor — und es entsteht nichts, bis Sie es drücken, denn ein Tastenkürzel trifft man leicht versehentlich. Drücken Sie es, öffnet sich das gewohnte **Chat with other AI** für diesen Tab, aus dem, was dort markiert ist. Und aus einem Terminal, dem Output-Bereich oder überall dort, wo ein Gespräch nicht hingehören kann, öffnet sich die vollständige Liste statt gar nichts.\n\n**New chat** in der Kopfzeile des Tabs fängt im selben Tab neu an. Das Gespräch, in dem Sie waren, wird archiviert — es liegt vollständig in **CoAI: switch conversations…** unter demselben Namen — und der Tab gehört wieder Ihnen, leer, und das Zitat, mit dem das alte begann, ist weggeräumt. Modell, Prompt und der Name des Tabs bleiben, wie sie waren, und die nächste Frage erreicht ein Modell, das nichts davon gehört hat. Genau darum geht es: ein langes Gespräch über eine Sache ist ein Modell, das sie immer noch mit sich trägt, wenn Sie nach einer anderen fragen — und auf einem Team-Server ist es zusätzlich das ganze Gespräch, das mit jeder Frage erneut gesendet und berechnet wird. Läuft noch eine Runde, wird sie zuerst beendet und abgewartet, damit die Antwort, auf die Sie gewartet haben, in dem archivierten Gespräch bleibt. Die Schaltfläche im Hinweis „dieses Gespräch ist voll“ ist dieselbe.\n\n**Wo es sich nicht sicher sein kann, fragt es.** Zwei Claude-Sitzungen gleichen Namens oder ein Gespräch über diese Datei, das unter einem anderen Ordner desselben Fensters liegt, öffnen die Liste auf genau diese eingeschränkt — mit einem Titel, der sagt warum, und mit dem Namen des Tabs bereits im Suchfeld, sodass das Gesuchte fast immer oben steht. Ein Backspace zeigt wieder alles. **Und wurde genau ein gespeichertes Gespräch aus einem Tab dieses Namens geöffnet — und ist gerade genau ein Tab dieses Namens offen —, öffnet es dieses, statt zu fragen** — wo es eine Antwort hat, nutzt es sie, und wo es nur eine Vermutung hat, zeigt es Ihnen die Vermutung.",
    whatCanGoWrong: "Das Kopieren der Auswahl braucht eine Windows-Sitzung: die dieses Rechners oder — aus einem WSL-Fenster — die, an der dieses Fenster hängt. Anderswo sagt die Tastenkombination das und verweist auf das Menü, das überall funktioniert. Lässt sich der Helfer nicht erreichen, oder startet er und wird nicht fertig, benennt die Meldung genau das, statt Ihre Auswahl zu beschuldigen. Stirbt der Prozess des Modells, sagt die Antwort danach, dass das Gespräch neu begonnen hat. Ein Reviewer auf einer anderen Laufzeit wird namentlich abgelehnt, statt still zu fehlen. Ein Neuladen des Fensters bewahrt das GESAGTE: jeder offene Chat-Tab kommt mit seinen Fragen und Antworten zurück, samt einer Zeile, dass das Gespräch durch das Neuladen geschlossen wurde. Das Modell dahinter ist fort — nichts läuft, bis Sie erneut fragen, und diese erste Frage trägt das Protokoll in eine neue Sitzung: das ist der Preis — oder, wenn Sie das Gespräch markiert haben, nur das unterhalb der Marke.\n\n**Ein Bild wird NAMENTLICH abgelehnt, statt ins Leere geschickt zu werden.** `codex` wird als UNGETESTET abgelehnt, nicht als unfähig — sein Konto lief mitten in der Messung in ein Limit, und das ist ein anderer Satz als ein gemessenes Nein —, und ein Reviewer auf einem Team-Server hat auf der Leitung noch gar keinen Platz dafür. Ein SVG wird abgelehnt, obwohl es ein Bild ist: es ist Markup mit Skript darin, und was hier geschieht, ist eine Datei an einen Prozess zu geben, der sie öffnen wird.\n\n**Die laufende Summe trägt bei zwei von drei Anbietern eine Tilde.** Nur `claude` meldet, was es berechnet hat; bei den anderen wird die Zahl aus Tokens hergeleitet, und ein geschätzter Zug macht die ganze Summe zur Schätzung. Die genaue Aufzeichnung, Zug für Zug, steht in **Show review rounds** — ein Gespräch ist auch dort eine Zeile. Und sie steigt: eine Frage an einen Team-Server trägt das ganze Gespräch mit, also ist ein langer Verlauf dort langsamer und teurer als ein kurzer. Das Mittel ist **Carry nothing above**, ohne den Verlauf zu verlieren — oder eine frische Stelle zu erfassen.\n\n**Ein Gespräch, das die Liste anbietet, kann schon fort sein.** Die Liste wird im Hintergrund aufgebaut und im Speicher gehalten — damit sie sofort aufgeht, statt Tausende Dateien zu lesen, während Sie warten —, und deshalb kann ein anderes Fenster ein Gespräch vergessen, zwischen dem Zeichnen der Liste und Ihrem Druck darauf. Dann wird es gesagt und die Zeile verschwindet, statt dass sich ein Tab auf nichts öffnet. Ein Gespräch, das DA ist und nicht gelesen werden kann, ist ein anderer Satz und behält seine Zeile: ein Ordner, der nicht geantwortet hat, oder ein Eintrag, den eine neuere Version dieser Erweiterung geschrieben hat, hat nichts verloren und geht wieder auf, sobald es geht.\n\n**Ein Gespräch, das in einem anderen VS Code-Fenster offen ist, steht in der Liste, lässt sich hier aber nicht öffnen.** Die Zeile sagt das, und ein Druck darauf sagt Ihnen, wo es ist. Ein Fenster kann kein anderes Fenster in den Vordergrund holen, und ein zweiter Tab auf dasselbe Gespräch gäbe ihm zwei Schreiber, die sich gegenseitig überschreiben — am Ende wäre das Gespräch in zwei Teile zerfallen. Wechseln Sie stattdessen in jenes Fenster. Aus demselben Grund lässt es sich von hier aus auch nicht vergessen: der Tab, der es hält, würde es einfach zurückschreiben.",
  },
  "the-consultant": {
    title: "Der Berater: ein zweiter Anbieter für eine festgefahrene KI",
    whatItIs: "Ein Werkzeug namens `consult`, das Ihr Assistent SELBST aufruft, wenn er zum zweiten Mal um denselben Fehler kreist. Es übergibt das Problem dem Modell eines anderen Anbieters, zusammen mit diesem Arbeitsverzeichnis und den noch nicht committeten Änderungen — jenes Modell liest den Baum NUR LESEND und antwortet mit einem Rat.\n\nNichts davon wird angewendet. Die Antwort kommt eingezount und als beratend markiert zurück, dem Assistenten wird ausdrücklich gesagt, dass es eine Meinung über Code ist, den der Berater nicht ändern kann, und die Korrektur wird weiterhin hier geschrieben und geprüft. Es ist ein Gespräch und keine Frage: ein paar Züge, damit das zweite Modell sagen kann „probieren Sie das, und sagen Sie mir, was ausgegeben wurde“ — und die Antwort auch hört.",
    why: "Zwei Runden derselben falschen Korrektur sind das Teuerste, was ein Assistent tut, und ausgerechnet das Modell, das den blinden Fleck erzeugt hat, kann ihn nicht sehen. Ein anderer Anbieter liest denselben Baum unvoreingenommen.\n\nVon Hand hieße das: einer zweiten KI das Problem noch einmal beschreiben — ohne Repository, ohne Diff und meist ohne das, was schon versucht wurde. Genau deshalb ist die zweite Antwort so oft die erste. Hier stellt der Server alle drei Teile selbst zusammen; der Assistent schickt nur das Problem in eigenen Worten.",
    setup: "**Let a stuck AI consult another vendor** ist der Schalter im Abschnitt **Consultant**. Er ist an und tut nichts, solange kein Assistent fragt.\n\nDarunter eine Zeile je Art von Aufrufer, denn wen eine festgefahrene KI fragt, hängt davon ab, welche KI feststeckt. Ausgeliefert: Claude Code fragt `codex`, Codex fragt `claude`, Gemini und alles andere fragen `codex` — niemals sich selbst.\n\n**Angeboten wird derselbe Katalog wie in *Add a reviewer***, unter denselben Namen: `Codex (OpenAI)`, `Antigravity (Google)`, `Claude`. Ein Eintrag, der kein Gespräch führen kann, steht mit seinem Grund darunter, statt still zu fehlen; ein Team-Server wird gar nicht angeboten — eine Konsultation geht nie über einen.\n\n**Das sind die EIGENEN Einstellungen des Konsultanten.** Das zweite Feld ist das Modell, und leer bedeutet die Voreinstellung dieser Laufzeit; daneben stehen, wo die Laufzeit sie hat, ihr eigener Endpunkt und der Pfad zu ihrer CLI. Ein Anbieter teilt hier nur den Namen — und damit den Schlüssel im Tresor — mit der Reviewer-Zeile gleichen Namens und sonst nichts: ändern Sie Modell oder Endpunkt eines Reviewers, bleibt der Konsultant, wo Sie ihn hingestellt haben, und löschen Sie diesen Reviewer, arbeitet der Konsultant weiter.\n\nEines sagt der Abschnitt offen, statt es zu verstecken: ein Konsultant auf der Codex-CLI mit eigenem Endpunkt — DeepSeek, OpenRouter, einer von Ihnen — lässt sich speichern und **kann in diesem Build nicht laufen**. Der Server lehnt ihn namentlich ab, und die Zeile sagt das dort, wo Sie wählen. Eine Zeile, die aus einer älteren Version noch auf einen Team-Server-Reviewer zeigt, sagt dasselbe und bietet keine Einstellungen mehr an, die sie nie nutzen kann. Der letzte Eintrag der Liste ist **Another OpenAI-compatible endpoint** — er fragt nach einem Namen und einer Basis-URL, genau wie *Add a reviewer*, und der Name ist der Schlüssel, unter dem die Zugangsdaten im Tresor-Eintrag liegen.\n\nDen eigenen Anbieter des Aufrufers zu wählen ist erlaubt, und die Zeile sagt, was davon zu halten ist: es lohnt sich nur mit einem stärkeren Modell, denn der Server sieht, welcher Anbieter fragt, und nie dessen Modell.",
    usage: "Sie drücken nichts. Das Snippet in Ihrer `CLAUDE.md` sagt dem Assistenten, wann es so weit ist — derselbe Fehler zweimal, oder Ihr Satz, dass es immer noch nicht behoben ist — und er ruft das Werkzeug selbst auf.\n\nDrei Zahlen begrenzen das. **Turns per consultation** ist, wie oft eine Beratung gefragt werden darf, standardmäßig fünf; dem Berater wird in JEDEM Zug gesagt, wie viele bleiben, damit der letzte antwortet statt eine weitere Rückfrage zu stellen. **Calls per session** ist, wie viele Beratungen eine Assistentensitzung eröffnen darf, standardmäßig zehn. **Close an idle consultation after, minutes** schließt einen liegengebliebenen Faden; eine spätere Frage ist dann eine neue Beratung mit vollem Budget.\n\n**Solange eine Beratung läuft, steht sie in der Seitenleiste**, oben im Abschnitt *Consultant*: wer wen fragt, der wievielte Zug es ist, und der Hinweis zum Arbeitsverzeichnis, falls er ausgelöst wurde. Endet sie, verschwindet sie — die Seitenleiste zeigt nur Laufendes — und jede Beratung, die es gegeben hat, ist eine Zeile in **Show review rounds** unter *Consultations*: woran es klemmte, was geraten wurde und was es gekostet hat.\n\nPing-Pong ist ausgeschlossen: eine in dieser Beratung bereits gestellte Frage wird abgelehnt, gleich in welchem Zug, der nächste Zug geschieht also erst, wenn Ihr Assistent wirklich etwas probiert hat und berichten kann. Was jede Beratung gekostet hat, steht in **Show review rounds**.",
    whatCanGoWrong: "**Der Berater kann nicht in Ihr Repository schreiben, und der Server prüft, statt zu vertrauen.** Er nimmt vorher und nachher einen Fingerabdruck des Baums; eine Beratung, WÄHREND DER sich der Baum GEÄNDERT hat, schlägt fehl und wird gemeldet, statt beantwortet zu werden — die Prüfung sieht, DASS sich etwas bewegt hat, nie WER, sodass auch Ihre eigene Änderung während des Wartens sie auslöst. Gelöscht oder zurückgesetzt wird dabei nichts — eine Datei, die Sie beim Warten geschrieben haben, gehört Ihnen.\n\n**Ein Rat ist Material, keine Anweisung.** Er kommt in einem Zaun, der nennt, welcher Anbieter ihn geschrieben hat und dass er nur beratend ist — damit Text in einem Repository, der an eine KI gerichtet ist, nicht dadurch befolgt wird, dass er Ihrer vorgelesen wird.\n\n**Das Gespräch liegt im Speicher des anderen Anbieters**, denn genau das macht eine Nachfrage möglich, und es enthält die uncommitteten Änderungen dieses Repositories. Das ist der Preis der Funktion, und es steht uns nicht zu, dort etwas zu löschen. Schalten Sie die Funktion ab, lehnt das Werkzeug MIT NAMEN ab, statt einen Assistenten rätseln zu lassen.",
  },
  "install-the-server": {
    title: "Hier anfangen: den MCP-Server installieren",
    whatItIs: "Die Erweiterung ist das Gesicht. Das Review macht `coai-mcp`, ein kleines Programm, das Ihr KI-Assistent startet. Solange es nicht installiert ist, reviewt niemand.",
    why: "Ein Review muss dort laufen, wo Ihr Code liegt, Hersteller-CLIs starten und minutenlang arbeiten. Das kann eine VS-Code-Erweiterung nicht, und ein Server, der einem VS-Code-Fenster gehörte, würde mit ihm sterben.",
    setup: "Öffnen Sie den Abschnitt **Server**. Dort steht, was installiert und was veröffentlicht ist, und eine Schaltfläche, wenn beides auseinandergeht — drücken Sie sie. Der Download wird gegen die `.sha256` des Releases geprüft, die Binärdatei landet im privaten Speicher der Erweiterung und kommt nicht in den `PATH`.\n\nDann Menü ⋯ → **Copy the MCP config block** und den Block in die Konfiguration Ihres Assistenten einfügen. Das passiert EINMAL. Starten Sie den Assistenten neu, damit er den Server hochfährt.",
    usage: "Danach kommen Sie selten in den Server-Abschnitt zurück: die veröffentlichte Version wird höchstens halbstündlich neu abgefragt, **Check again** fragt sofort.\n\nJede Plattform hat ihre eigene Binärdatei. Zu jedem Release erscheinen Builds für Windows, macOS und Linux; eine Maschine ohne eigenen Build sagt das ehrlich, statt einen fremden zu laden.",
    whatCanGoWrong: "Steht im Panel, die veröffentlichte Version sei nicht lesbar, wurde GitHub nicht erreicht. Nichts ist kaputt, der installierte Server läuft.\n\nZeigt Ihr Assistent nach dem Einfügen keine Werkzeuge, wurde er nicht neu gestartet. Im Block steht der exakte Pfad zur Binärdatei; ein von einer anderen Maschine kopierter Block zeigt auf einen Pfad, den es hier nicht gibt.",
  },
  "choose-reviewers": {
    title: "Dann: wählen Sie, wer prüft",
    whatItIs: "Der Abschnitt **Reviewers** ist die Runde fremder Modelle, die Ihren Plan und Ihren Code lesen wird. Jede Zeile ist ein Anbieter: ein Häkchen zum Einbeziehen, eine Modellauswahl, ein ▶ um dessen CLI im Terminal zu öffnen, ein ⤓ um diese CLI zu installieren, ein ⟳ das grün wird, sobald eine neuere Version veröffentlicht ist, seine zwei Preise pro Million Token — und neben jedem Preis die Stufe, für die er zahlt: **reviews plans** neben dem Eingangspreis, **reviews code** neben dem Ausgangspreis. Dann **remove**.\n\nEine Team-Server-Zeile hat hier keine Preise, auf die sie passen könnten — ihr CLI läuft auf dem Server, und ihr Preis ist das Abonnement der Firma —, also stehen ihre beiden Stufen-Häkchen in einer eigenen Zeile.",
    why: "Der ganze Punkt ist, dass der Prüfer nicht der Autor ist. Eine zweite Meinung desselben Modells, das den Code geschrieben hat, ist weniger wert als eine erste Meinung eines anderen — und zwei Anbieter, die sich auf einen Befund einigen, sind das stärkste Signal, das dieses Produkt hervorbringt.",
    setup: "**＋ Add a reviewer** bietet die Anbieter an, die dieser Build kennt: Codex, Antigravity (Gemini, Claude und GPT-OSS über ein Abonnement), ein zweites Claude, DeepSeek, OpenRouter und eine leere Zeile für jeden OpenAI-kompatiblen Endpunkt.\n\nDie meisten authentifizieren sich selbst: ist die CLI auf dieser Maschine angemeldet, braucht es keinen Schlüssel. ▶ in einer Zeile öffnet ein Terminal mit dieser CLI — dort melden Sie sie an, und dort steht ihr eigener Verbrauchsbefehl schon getippt und wartet auf Enter. ⤓ öffnet dasselbe Terminal mit dem INSTALLATIONS-Befehl — dem offiziellen des Anbieters, für das Betriebssystem, in dem dieses Terminal wirklich läuft. VS Code an WSL angebunden bekommt den Linux-Befehl, nicht den PowerShell-Befehl.",
    usage: "**⟳ sagt Ihnen VOR dem Drücken, ob es etwas zu aktualisieren gibt.** Grün heißt, der Anbieter veröffentlicht eine neuere Version als die auf dieser Maschine; grau heißt, Sie sind auf der neuesten — oder eine der beiden Zahlen war nicht lesbar. Beide stehen im Tooltip, die Farbe ist also nie das einzige Signal. Ein Druck öffnet ein Terminal mit demselben Befehl wie ⤓, denn bei jeder CLI hier IST das erneute Ausführen des Installers die Aktualisierung: OpenAI druckt eine Zeile unter *Install Codex* und unter *Update Codex*, Anthropics native Installation ist dasselbe Skript, und `agy` hat gar keinen update-Unterbefehl.\n\nZwei Prüfer sind das nützliche Minimum, weil Übereinstimmung das Signal ist. Drei kosten dreimal so viel und sagen selten dreimal so viel.\n\nDie Modellauswahl zeigt, was diese CLI auf dieser Maschine wirklich erreicht: bei Codex der eigene Modell-Cache, bei den anderen eine geprüfte Liste. **another model…** nimmt jede exakte id.",
    whatCanGoWrong: "Den letzten Prüfer zu entfernen wird abgelehnt: eine Runde ohne Teilnehmer prüft nichts.\n\nEin Anbieter, dessen CLI nicht installiert ist, sagt das in **providers** vor einer Runde, nicht mitten darin. Gemini ist eigens als RETIRED markiert — Google hat Code Assist für Einzelkonten geschlossen, und diese CLI verweigert nun, bevor sie ein Modell erreicht. Nehmen Sie Antigravity.",
  },
  "a-local-model": {
    title: "Ein Modell auf dem eigenen Rechner als Prüfer",
    whatItIs: "Ein Prüfer namens **local**, hinter dem eine Engine auf diesem Rechner steht — Ollama, ein vLLM oder alles, was dieselbe OpenAI-kompatible Form spricht. Seine Modellauswahl ist das, was SIE installiert haben, mit Parametergröße, Quantisierung und Größe auf der Platte: was installiert ist, ist eine Tatsache über Ihren Rechner und keine Liste, die diese Erweiterung mitbringen könnte.",
    why: "Er kostet pro Runde nichts, und nichts verlässt das Haus. Damit ist er der Prüfer, den man sich bei jedem Push leisten kann — und der einzige für eine Änderung, die nirgendwohin geschickt werden darf. Er ist eine ANDERE Art Prüfer als die gehosteten, nicht eine billigere: das Panel gibt es, damit man mischt.",
    setup: "Über **＋ Add a reviewer** hinzufügen; die Zeile füllt sich selbst: die Engine wird auf 11434 (Ollama) und 8000 (vLLM) gesucht, und die Auswahl zeigt, was sie hat. Wird nichts gefunden, sagt die Zeile wo gesucht wurde und warum es nicht ging — abgelehnt, Zeitüberschreitung, seltsame Antwort — statt eine leere Liste zu zeigen.\n\nDas Endpunktfeld ist für alles, was die Suche nicht sieht: ein vLLM auf einem anderen Port, ein Rechner im Netz, eine Engine hinter einem Proxy. Es will die OpenAI-kompatible Basis, endend auf `/v1` — **nicht** die Adresse, die man im Browser öffnet: Ollama bedient seine eigene API an der Wurzel und die kompatible unter `/v1`, und eine Basis ohne das scheitert bei der ersten Prüfung an einem 404, der wie ein Modellproblem aussieht.\n\n⟳ fragt die Engine erneut. Eine erfolgreiche Suche wird eine Minute zwischengespeichert, damit das Panel nicht bei jedem Neuzeichnen Modelle auflistet — ein gerade geholtes Modell ist also noch nicht da; genau dafür ist der Knopf.",
    usage: "**Geben Sie ihm Platz.** Eine Prüfung ist der Prompt, der Plan oder das Diff und das Schema, alles in einer Anfrage. Ein Modell mit kleinem Kontextfenster lehnt ab, statt schlecht zu antworten — ehrlich, und die Runde ist trotzdem verbraucht. Wo Sie die Wahl haben, nehmen Sie die Variante mit dem größeren Kontext.\n\nDiese Zeile hat kein ▶, kein ⤓ und kein Update-⟳: das sind die Knöpfe einer CLI, und hier gibt es nichts anzumelden, zu installieren oder zu aktualisieren. Token WERDEN gezählt — die Engine meldet sie und sie erscheinen in der Ausgabenübersicht — aber Geld ist ein Strich: ein Modell auf Ihrer eigenen Hardware hat keine Token-Rechnung. Es kostet Strom und eine belegte Karte, und beides sieht dieses Panel nicht.",
    whatCanGoWrong: "**Ein Endpunkt, der nicht auf diesem Rechner ist, wird in der Zeile angesagt.** Jede Prüfung schickt den Prompt dorthin — Ihren Plan, Ihre Diffs und die Dateiinhalte drumherum. Genau dafür ist eine entfernte Engine da, und genau so verlässt Quelltext versehentlich das Haus, deshalb nennt die Zeile den Host und was dorthin geht. Benutzen Sie nur einen, den Sie kontrollieren.\n\n**In einem an WSL angebundenen Fenster stehen einer Engine auf der Windows-Seite ZWEI Dinge im Weg.** Sie ist an `127.0.0.1` gebunden — starten Sie sie mit `OLLAMA_HOST=0.0.0.0`; und `127.0.0.1` auf dieser Seite ist WSLs eigenes Loopback, nicht der Windows-Host, also muss der Endpunkt auf die Adresse des Windows-Hosts zeigen.\n\n**Ein Modell, das die Engine nicht mehr führt,** bleibt mit *NOT on this engine any more* in der Liste — statt zu verschwinden (das würde Ihren Prüfer still austauschen) oder normal auszusehen (das würde eine Runde an ein Modell schicken, das 404 antwortet).",
  },
  "teach-your-ai": {
    title: "Und: Ihrer KI sagen, das Gate zu benutzen",
    whatItIs: "Menü ⋯ → **Copy the CLAUDE.md snippet** liefert einen Absatz, der in das Repository kommt, das Sie reviewen lassen wollen. Er sagt der dort arbeitenden KI, dass es ein Review-Gate gibt und in welcher Reihenfolge es benutzt wird.",
    why: "Ein Assistent mit Werkzeugen, aber ohne Anweisung, kommt nicht von selbst darauf, eine Review-Sitzung zu öffnen. Dieser Absatz IST die Anweisung, und er lebt im Repository statt in der Erweiterung, weil er eine Eigenschaft des Projekts ist und nicht Ihres Editors.",
    setup: "Kopieren, in die `CLAUDE.md` jenes Repositories einfügen (oder in das, was Ihr Assistent liest), committen. Er nennt kein Repository: die KI, die ihn liest, sitzt ohnehin in einer Arbeitskopie, die sie selbst benennen kann.",
    usage: "Danach öffnet der Assistent eine Sitzung, schickt den Plan, arbeitet die Befunde ab, implementiert, schickt das Diff und arbeitet erneut ab. Sie sehen das unter **Active rounds** und beantworten, was er eskaliert.",
    whatCanGoWrong: "Nichts erzwingt diesen Absatz. Der Assistent kann ihn ignorieren, und das Gate kann sich nicht selbst aufrufen. Was es KANN: sich weigern, Code zu reviewen, solange der Plan nicht durch ist — und das tut es.",
  },
  "the-gate": {
    title: "Das Tor: Runden, die Schwelle, und was passiert, wenn sie aufgebraucht sind",
    whatItIs: "Einstellungen, die entscheiden, wann eine Prüfung vorbei ist. **Rounds** ist, wie viele Versuche eine ROLLE bekommt. **Passes at or under** ist, wie viele ihrer blockierenden Befunde hinnehmbar sind. **When the rounds run out** ist, was passiert, wenn es nie dorthin kommt.",
    why: "Ohne Grenze endet eine Prüfschleife nie: es gibt immer noch einen Befund. Die Schwelle sagt als Zahl, was „gut genug“ heißt, bevor der Streit beginnt.",
    setup: "JEDE Rolle hat ihre eigenen Runden und ihre eigene Schwelle, eingestellt neben den Prompts dieser Rolle: Architektur mag zwei Durchgänge mit verschiedenen Linsen wert sein, Performance nur einen, und ein gemeinsames Budget lässt die günstigste Rolle für die teuerste zahlen. Jede Code-Rolle hat zudem ein **Kästchen in ihrer eigenen Überschrift**: abgehakt entfernt, nimmt die Rolle an der Runde überhaupt nicht teil — kein Prüfer wird für sie gestartet, nichts, was sie gefunden hätte, zählt, und sie leiht der Stufe weder ihre Runden noch ihre Schwelle. Ihre Zahlen und Prompt-Auswahlen bleiben erhalten und kommen unverändert zurück, wenn Sie sie wieder ankreuzen. Die letzte lässt sich nicht abwählen: eine Runde ohne jeden Prüfer wird nie aufgelöst. Die Planprüfung hat eine Rolle und kein Kästchen. Ein Befund zählt gegen die Schwelle DER Rolle, die ihn erhoben hat, also kann eine laute Rolle nicht die Toleranz einer anderen verbrauchen. Eine Stufe besteht, wenn jede Rolle auf oder unter ihrer eigenen Zahl liegt, und überarbeitet nur für Rollen, die noch Runden haben.\n\nDaneben steht der zweite Schalter, **Deal the lenses across vendors**: aus — jeder Anbieter beantwortet dieselbe Frage, und die Übereinstimmung zweier Anbieter ist eine Tatsache, mit der das Tor arbeiten kann; ein — jede Linse wird einmal gefragt, bei halb so vielen Starts, und diese Übereinstimmung ist weg.\n\nStandard: drei Planrunden mit Schwelle zwei, je zwei Runden pro Code-Rolle mit Schwelle drei, Verteilen aus, Politik *Ask a human*. Zur Schwelle zählen nur **blocking** und **major**; minor und nit blockieren nie.\n\nEin von zwei Anbietern erhobener Befund zählt EINMAL. Ein Befund, den Sie mit Begründung abgelehnt haben, zählt nicht wieder, bis ein Prüfer ihn mit einem wirklich neuen Argument erneut erhebt.",
    usage: "*Ask a human* ist die ehrliche Voreinstellung: das Tor hält an und legt die Entscheidung vor Sie. *Continue anyway* macht weiter und sagt laut, dass Befunde offen bleiben — und rührt keinen davon an, genau so wird ein Tor zur Dekoration. *Good enough — take what’s true and move on* ist das Dazwischen: die KI liest die offenen Befunde, wendet die wahren und nützlichen an, lehnt den Rest mit Begründung ab und geht weiter. *Escalate* steigt eine Leiter — mehr Prüferaufwand, dann ein stärkeres Prüfermodell, dann ein stärkerer Schiedsrichter — und gibt der Stufe jedes Mal einen frischen Satz Runden.\n\nDrei Schalter unter diesem Feld ändern nichts an dem, was das Gate ENTSCHEIDET — sie sind Anweisungen, die es der aufrufenden KI zurückgibt, und sie sind aus, bis Sie sie einschalten. **Autonom arbeiten**: Der KI wird gesagt, was autonom BEDEUTET, nicht nur, es zu sein — jeder Fehler bekommt einen Red-Green-Red-Test; Dokumentation, README, Manifest und Moduldokumente werden mit jeder Änderung aktualisiert; vor einem Release laufen ALLE Tests; wo das Repository einen Release- oder Pull-Request-Prozess hat, wird er durchlaufen, und die automatischen Kommentare eines Pull Requests werden fünf Minuten später gelesen und behoben; ein automatisches Deploy wird gegen dev, stage oder test geprüft und seine Logs gelesen; der Code wird gegen die Regeln des Repositories nachgelesen; und die KI sagt, dass sie autonom arbeitet und was sie gerade schreibt. Fragen, die nicht blockieren, werden gesammelt und am Ende gemeinsam gestellt; eine blockierende sofort, aber erst nachdem alle weiteren blockierenden gesammelt sind — damit Sie einmal unterbrochen werden. **Den Plan in Epics und Stories teilen**: Nach einem bestandenen Plan wird die KI angewiesen, ihn in 2-4 Epics und jedes in 2-4 Stories zu teilen und jede Story vollständig abzuschließen — Diff hier prüfen, korrigieren, dokumentieren, testen, committen, dann die nächste. Die Anweisung ergeht einmal pro Assistent: Jedes Epic kommt für seine eigene Planprüfung zurück und hört nicht «teile erneut», sondern «du bist ein TEIL einer laufenden Aufteilung» — bau es als eine Einheit und schließe es sauber ab. Sonst hätte der Vorgang kein Ende. **Mit Fable teilen**: Ist ein Fable-Anbieter konfiguriert, gehen die Aufteilung selbst und die teuren Stories (Zahlungen, Sicherheit, Architektur) an Fable in seiner höchsten Version, die gewöhnlichen an Opus.",
    whatCanGoWrong: "Eine Schwelle von null heißt, dass jeder Befund jeder Schwere blockiert, was in der Praxis heißt, dass eine Prüfung nie besteht.\n\nRunden gelten pro STUFE: Plan-Tor und Code-Tor bekommen je die volle Zahl.",
  },
  "prompts-per-round": {
    title: "Prompts pro Runde: welche Frage jede Runde stellt",
    whatItIs: "Jede Prüferrolle hat einen universellen Prompt und fünf enge Linsen. Hier wird gewählt, welchen Prompt jede RUNDE dieser Rolle nutzt, und es steht neben Runden und Schwelle derselben Rolle, weil diese drei Einstellungen gemeinsam eine Frage beantworten.\n\nDie letzten zwölf Linsen wurden gemessen, bevor sie ausgeliefert wurden: je drei Formulierungen, je zwei Läufe. Die drei Formulierungen erwiesen sich als drei FORMEN, und sie finden gleich viel — sie unterscheiden sich darin, wie viel einen zweiten Lauf übersteht: eine als Aufgabe geschriebene Linse (*„führe es zweimal aus, eine Millisekunde versetzt, und schildere beide“*) wiederholt sich um die Hälfte häufiger als dieselbe Frage als Prüfliste.",
    why: "Ein Prompt pro Rolle für immer ist die richtige Voreinstellung und die falsche Obergrenze. Wird ein Modell gebeten, auf alles zu schauen, verteilt es sich dünn, und eine zweite Runde derselben breiten Frage gibt meist dieselben breiten Antworten.",
    setup: "Ein Wähler pro Runde pro Rolle; jede Option trägt ihren Zweck als Tooltip. Eine Runde, die Sie nicht angefasst haben, zeigt, was der Server für sie wirklich starten wird — der Wähler ist nie eine Vermutung und nie ein Prompt, den niemand ausführt.\n\n**Runde eins jeder CODE-Rolle ist der Konventionsdurchgang, sofern Sie nichts anderes wählen.** Er beurteilt das Diff nach den Regeln, die dieses Projekt aufgeschrieben hat — nach nichts sonst — und ein Befund muss den Satz zitieren, den er bricht. Ein Repository ohne Regeldateien fällt auf den universellen Prompt dieser Rolle zurück, denn ein Konventionsdurchgang ohne Konventionen hat nichts zu sagen.\n\nJede andere ungesetzte Runde ist die universelle Frage dieser Rolle. Eine Linse wird gestellt, wenn Sie sie stellen: eine automatische Rotation gibt es nicht mehr. Es gab eine, sie hatte keinen Schalter, den das Panel erreichen konnte, und ihre einzige verbliebene Wirkung war, dass dieser Wähler einen Prompt nannte, den der Server nicht ausführt.",
    usage: "**Deal the lenses across vendors** ist der Schalter neben diesen Wählern, und er ist der, der ändert, wie eine Runde ausgegeben wird: aus — jeder Anbieter beantwortet jede Frage dieser Runde; ein — die Prompts der Runde werden einer pro Anbieter verteilt, und eine Runde kostet einen Start pro Anbieter statt einen pro Prompt pro Anbieter. Bezahlt wird mit Übereinstimmung: zwei Anbieter, die denselben Befund melden, sind das stärkste Signal dieses Produkts, und eine verteilte Runde kann es nicht erzeugen. Genau deshalb ist er standardmäßig aus.\n\nWollen Sie zwei verschiedene Linsen auf einer Änderung, setzen Sie sie auf zwei Runden und lassen beide laufen. Es wurde gemessen: über zwei Code-Runden fand das Ausgeben an verschiedene Linsen WENIGER verschiedene Befunde als zweimal die universelle Frage (17 gegen 25), für weniger Geld — weshalb es niemand für Sie tut.\n\nDen vollen Text jedes Prompts finden Sie in **The prompts, in full**.",
    whatCanGoWrong: "**Was die Messung NICHT belegt.** Über drei Pläne fand die Vereinigung dreier Linsen etwa doppelt so viel wie jede einzelne — und dieses Ergebnis übersteht seine eigene Kontrolle nicht: DERSELBE Prompt auf DEMSELBEN Text ergab dreimal 6, 4 und 5 Befunde mit Überschneidungen von 3, 1 und null. Streuung zwischen Läufen allein erklärt die Spanne. Die Linsen werden angeboten, weil man mit ihnen nützlich zielt, nicht weil gezeigt wurde, dass sie mehr finden.",
  },
  "limits": {
    title: "Grenzen: wie viele gleichzeitig und wie lange auf jeden gewartet wird",
    whatItIs: "**Reviewers at once** begrenzt den ganzen Fächer. **Per vendor** begrenzt einen Hersteller. **Reviewer timeout** — wie lange ein Reviewer laufen darf. **Wait for you** — wie lange eine Eskalation auf einen Menschen wartet, bevor sie aufgibt.",
    why: "Eine Code-Runde sind sechs Prozesse, die in derselben Sekunde starten wollen: drei Rollen mal zwei Hersteller. Ohne Grenze treffen genau hier Prozesslimits des Systems, die Lock-Dateien der CLIs und die Herstellerlimits gleichzeitig ein — und jedes sieht aus wie ein Timeout, solange es nicht beim Namen genannt wird.",
    setup: "Voreinstellung: drei gleichzeitig, zwei je Hersteller. Die Grenze je Hersteller existiert, weil ein Ratenlimit pro Hersteller gilt: eine einzige gemeinsame Grenze würde alle Plätze bereitwillig an einen vergeben.\n\nDas Reviewer-Timeout sind zehn Minuten. Eine Code-Runde auf einem großen Diff braucht drei bis fünf.",
    usage: "Erhöhen Sie die gemeinsame Grenze auf einer Maschine mit freien Kernen und senken Sie sie auf dem Notebook, auf dem Sie nebenher arbeiten. Wer in Herstellerlimits läuft, senkt die Grenze JE HERSTELLER.",
    whatCanGoWrong: "Das Timeout tötet den ganzen Prozessbaum, nicht nur die CLI: die Kindprozesse eines Reviewers überleben ihn nicht.\n\nDas Ablaufen von **Wait for you** ist keine Absage: die Eskalation bleibt im Panel offen, und die KI wird angewiesen, Sie im Gespräch zu fragen.",
  },
  "language-and-translator": {
    title: "Sprache: die Fragen sind englisch",
    whatItIs: "Hier gibt es nichts mehr einzustellen. Eine `call_human`-Frage erreicht Sie als ein fester englischer Satz mit drei Knöpfen, und Ihre Antwort geht genau so zurück, wie Sie sie gegeben haben.",
    why: "Es gab einmal einen Übersetzer: die Frage war Prosa, die eine KI geschrieben hatte, Sie mussten sie lesen, und Sie antworteten in eigenen Worten. Drei Knöpfe haben all das entfernt. Ein Unterprozess pro Eskalation, der ablaufen, verweigern oder in der falschen Sprache antworten kann, ist ein bewegliches Teil, das nichts verdient.",
    setup: "Nichts. Die Bedienelemente **Ask and answer in** und **Translated by** sind fort, mit ihnen die Einstellungen `COAI_LANGUAGE` und `COAI_TRANSLATOR_*` dahinter.",
    usage: "Die Sprache DIESER Hilfe ist getrennt und weiterhin Ihre: der Wähler oben auf diesen Seiten schaltet sie um, gespeichert als `coai.helpLanguage`. Geändert hat sich die Prüferseite, nicht die Leseseite.",
    whatCanGoWrong: "Hier kann nichts mehr scheitern, was der Punkt war. Tippen Sie Freitext auf einem Knopf, der das anbietet, erreicht er die KI unvermittelt — mehr wert als dieselben Worte, von einem dritten Modell in eine andere Sprache gebracht.",
  },
  "vendor-keys": {
    title: "Hersteller-Schlüssel: nur, wenn eine CLI sich nicht selbst anmelden kann",
    whatItIs: "Ein einzelner `config`-Eintrag in CredsForDevs, der je einen Schlüssel für jeden Hersteller hält, der einen braucht. Das Panel zeigt, welcher Ihrer Reviewer ihn wirklich benötigt.",
    why: "Die meisten Reviewer-CLIs sind auf Ihrer Maschine bereits angemeldet und brauchen gar keinen Schlüssel. Wer einen braucht — ein eigener Endpunkt, DeepSeek, OpenRouter — sollte ihn nicht in eine Einstellungsdatei tippen.",
    setup: "Nur nötig, wenn die Reviewer-Zeile es sagt. Legen Sie in CredsForDevs einen `config`-Eintrag an, hinterlegen Sie die Schlüssel als `{\"deepseek\": \"sk-…\"}` und tragen Sie dessen Kennung unter **CredsForDevs config key** ein.",
    usage: "Der Server liest den Eintrag beim Start und reicht jeden Schlüssel über die Umgebung an seinen Hersteller weiter, nie über die Kommandozeile. Ein gewechselter Schlüssel gilt ab dem nächsten Serverstart.",
    whatCanGoWrong: "Ein Hersteller, der einen Schlüssel braucht und keinen hat, erscheint in **providers** als `unavailable` mit Grund und fällt aus dem Fächer — er wird nicht stillschweigend übersprungen.",
  },
  "bugz": {
    title: "Bugz: die Fehler, die Ihr Gate bereits gefunden hat",
    whatItIs: "Jeder ANGENOMMENE Befund ist ein Fehler, den ein Mensch bestätigt hat. **Bugz** liest sie als Material zurück, nicht als Protokoll: es findet die Methode, um die es ging, findet den Commit, der sie behoben hat, und behält das Paar. **Collect** sucht; **Review bugs** ist der Ort, an dem Sie entscheiden, was bleibt.",
    why: "Ein Review-Gate erzeugt etwas, das die meisten Werkzeuge wegwerfen: Paare von Code, der falsch war und dann richtig, jedes von einem Menschen bestätigt statt geraten. Gemessen an einer echten Datenbank am 15.09.2026 — 8 687 Befunde verengen sich auf 462 brauchbare über 115 Stories und 15 Repositories.\n\n**Gelesen wird nur, was ohnehin auf Ihrer Maschine liegt.** Die Befunde stammen aus Ihren eigenen Runden, der Code aus Ihrer eigenen git-Historie. Das Sammeln sendet nichts irgendwohin.",
    setup: "Wählen Sie ein **Ranking-Modell** — angeboten werden nur Engines, die auf dieser Maschine laufen, und das ist eine Entscheidung, keine Vorsicht: Titel und Beschreibung eines Befundes sind die eigenen Worte der Reviewer über Ihren Code, und sie sind NICHT anonymisiert. Die Anonymisierung läuft später und nur über Quelltext. Dieser Schritt liest sie also hier — oder gar nicht.\n\nDann **Collect** drücken. Der Abschnitt zeigt den Lauf, während er läuft, und am Ende, was aus jedem Kandidaten wurde.",
    usage: "Ein Lauf entscheidet jeden unbearbeiteten Befund und schreibt auf, was er entschieden hat: **collected** mit dem behebenden Commit, **skipped** mit einem Grund, oder **failed**. Skipped ist gewöhnlich — eine Sprache, die hier niemand parst; ein Commit, den kein Branch mehr erreicht; eine Behebung, die nicht in diesem Repository liegt — und der Grund bleibt erhalten, damit die Quote eine Messung ist und kein Achselzucken.\n\nDer Lauf wird erinnert; das Fenster zu schließen oder F5 zu drücken ändert, was Sie SEHEN, und nie, was geschehen ist. Drücken Sie später wieder Collect, und er nimmt die, die noch niemand angesehen hat.\n\n**Who holds a key** ist die andere Hälfte: die Beitragenden-Schlüssel, die Ihr Ingest-Server ausgegeben hat, was jeder gesendet hat, und die Schaltfläche, die einen beendet. Führen Sie zuerst **Set the bugs admin key** aus — er liegt im Secret Storage des Editors auf diesem Rechner, nie in den Einstellungen: Einstellungen synchronisieren, und ein Administrationsschlüssel, der Ihnen auf einen anderen Rechner folgt, ist einer, für den niemand geradesteht.\n\nEin Schlüssel wird EINMAL angezeigt, bei der Ausgabe. Schließen Sie das Fenster, bevor Sie ihn kopiert haben, bietet ihn der Tab beim nächsten Öffnen erneut an und kann ihn für Sie widerrufen — der Server zeigt ihn kein zweites Mal. Das Widerrufen fragt vorher und nennt die Notiz des Schlüssels und den Monat der letzten Nutzung, denn die Kennungen sind hexadezimal und sehen einander ähnlich.",
    whatCanGoWrong: "**Ein unterbrochener Lauf sagt das auch.** Schließen Sie das Fenster mittendrin, hört die Zeile auf zu melden, dass sie lebt; beim nächsten Nachfragen wird sie als unterbrochen markiert, statt weiter laufend auszusehen. Was bereits entschieden war, bleibt: jeder Kandidat wurde geschrieben, sobald er entschieden war.\n\n**Mehr als die Hälfte der Commits ist unerreichbar, und das ist normal.** Squash-Merge löscht den Branch, auf dem eine Runde lief — 55,7 % der gemessenen Kandidaten — aber die Objekte überleben, also lässt sich die Methode weiterhin lesen und die Suche weiterhin durch die nächste Runde derselben Sitzung begrenzen.\n\n**Ein nicht lokales Modell wird abgelehnt, woher es auch kommt.** Die Palette bietet keines an, und der Collector lehnt es ohnehin ab, bevor er einen einzigen Befund liest — eine Auswahlliste ist keine Garantie.",
  },
  "recent-rounds": {
    title: "Active rounds: was gerade läuft",
    whatItIs: "Jede laufende Runde, neueste oben, vollständig: was reviewt wird, die Stufe, der Branch, wie lange sie schon läuft — und darunter jeder Reviewer, den die Runde gestartet hat, mit dem, was er bisher getan hat, wie viele Funde er eingereicht hat, wie lange ER gebraucht hat und was er gelesen hat.",
    why: "Ein Review dauert Minuten, und worauf man wartet, ist kein Verdikt, sondern die Reviewer, die es erzeugen. Eine abgeschlossene Runde ist eine andere Frage — „was war“ — und das ist ein Protokoll, das eine Tabelle mit Filtern, Sortierung und Suche braucht, keine Seitenleiste. Die Seitenleiste behält also nur die Gegenwart.",
    setup: "Nichts einzustellen. Der Server schreibt eine Runde beim Start auf die Platte und aktualisiert sie, während die Reviewer vorankommen — das Bild überlebt ein neu geladenes Fenster, einen Neustart der Erweiterung und einen abgeschossenen Server.",
    usage: "Es gibt nichts anzuklicken: eine laufende Runde ist bereits offen, und wenn sie fertig ist, verlässt sie die Seitenleiste. Alles, was je gelaufen ist — fertig, unterbrochen, jeder Reviewer, jede Zahl — steht unter **Show review rounds** (das ⋯-Menü im Titel des Panels).\n\nDieses Protokoll enthält auch Ihre GESPRÄCHE, nicht nur Runden. Die Spalte **Kind** sagt, was eine Zeile ist — *review* oder *conversation* —, und der Filter daneben grenzt auf eines ein oder zeigt beide: „Was hat mich heute gekostet“ ist selten eine Frage nach nur einem davon. Ein Gespräch lässt die Spalten Repository, Branch und Stufe leer: ein Chat hängt an keinem Branch.\n\nDie Spalte **Took** im Protokoll nennt zwei Zeitspannen, nicht eine: `2m 10s · 5m 0s` ist, wie lange die Reviewer liefen, und dann, wie lange das ENTSCHEIDEN dauerte — vom Ende der Runde bis zu ihrer letzten Entscheidung. Eine Runde, über die niemand entschieden hat, zeigt eine Zahl, ein Gespräch ebenso. Ein `resolve`-Aufruf stempelt alles, was er berührt, mit einem einzigen Zeitpunkt; bei einer gewöhnlichen Runde ist die zweite Zahl also das Entscheiden, bei einer Runde, zu der Sie nach dem Mittagessen zurückkamen, zählt das Mittagessen mit.\n\n**Jede Zeile endet mit Export, und das ganze Protokoll kann als Datei herausgehen.** Der **Export** einer Runde schreibt eine CSV-Datei dorthin, wo Sie wollen: wann sie lief, auf welchem Branch und in welchem Repository, ihr Urteil, an wie vielen Befunden sie hing, beide Zeiten, die Token, die drei Kostenzahlen und eine Zeile je Reviewer — und danach eine Zeile je BEFUND, die die Spalten der Runde noch einmal trägt, dazu Ihre Entscheidung darüber, in denselben Worten wie auf der Seite (*took*, *declined*, *open*), mit dem Grund einer Ablehnung daneben.\n\nFür mehr als eine Runde haken Sie sie an. Das Kästchen in der Kopfzeile wählt jede Runde, auf die die Filter gerade passen — über alle Seiten hinweg, nicht nur die zwanzig auf dem Bildschirm —, und die Schaltfläche sagt, wie viele Sie gewählt haben und wie viele davon außer Sicht sind (*Export 41 selected (3 hidden)…*). Filtern macht eine Auswahl nie rückgängig; **Clear selection** verwirft sie in einer Geste. Ein Massenexport meldet, wie viele Runden er gelesen hat, und lässt sich abbrechen — halten Sie ihn an, wird nichts geschrieben —, und über fünfhundert Runden fragt er vorher nach.",
    whatCanGoWrong: "Eine Runde, die ein abgestürzter Server zurückließ, wird beim nächsten Start auf *interrupted* gesetzt und verschwindet hier; im Protokoll bleibt sie. Steht hier *Nothing is running*, während Ihr Assistent sagt, er reviewe gerade, schreibt der Server, mit dem er spricht, woanders hin — ein `COAI_DATA_DIR` in seiner Konfiguration, das dieses Fenster nicht teilt.\n\nIn einer exportierten Datei bleibt eine fehlende Messung fehlend: eine Runde, deren Token niemand festgehalten hat, lässt die Zelle leer statt null — denn null ist eine Zahl, die jemand gemessen hat. Eine Runde, deren Befunde nicht GELESEN werden konnten, wird nie als Runde geschrieben, die nichts gefunden hat: die Spalte `findings_read` sagt für jede — *loaded*, *not recorded* oder *failed* —, die Befundspalten bleiben in den letzten beiden Fällen leer, und die Meldung nach dem Export nennt jede Runde, die nicht gelesen werden konnte. Konnte gar nichts gelesen werden, wird keine Datei geschrieben und der Speicherdialog öffnet sich nicht.\n\nNichts in der Datei kann beim Öffnen ausgeführt werden: ein Branch oder ein Titel, der mit `=`, `+`, `-` oder `@` beginnt, wird als Text geschrieben — auch dann, wenn er sich hinter einem Leerzeichen versteckt. Der Zeitpunkt wird zweimal geschrieben — wie gespeichert, in UTC, und nach der Uhr Ihrer Maschine mit angegebenem Versatz —, denn eine Datei kann nicht wissen, in welcher Zeitzone sie in einem Jahr gelesen wird. Den Speicherdialog abzubrechen tut nichts und sagt nichts; ein fehlgeschlagener Schreibvorgang sagt, was fehlschlug, und behauptet nie einen Erfolg. Gegen ein `coai-mcp`, das älter ist als dieses Release, funktioniert ein Massenexport weiterhin — eine Runde nach der anderen, vier auf einmal.",
  },
  "what-each-ai-has-used": {
    title: "Was jede KI verbraucht hat: Token, Geld und Zeit",
    whatItIs: "Ein Balken pro Anbieter über einen Tag, eine Woche, einen Monat oder ein Jahr: Token hinein und hinaus, **Geld**, wie viele Läufe, wie viele gescheitert, Gesamt- und Durchschnittszeit — und eine Zeile unten, die alle Anbieter zusammenzählt. Chat-Züge werden ebenfalls gezählt, und sie haben jetzt einen eigenen Abschnitt auf diesem Reiter: oben **Reviewers**, eine Linie, darunter **Chat** — eine Karte pro Anbieter UND Modell, in der Form der Prüfer-Karten darüber, denn ein Gespräch wechselt das Modell, und ein Preis gehört zum Modell. Eine Chat-Karte führt beide Preise, was sie im gewählten Zeitraum gekostet hat, was sie **insgesamt** gekostet hat — unabhängig vom oben gewählten Zeitraum — und zwei Zähler: **Asked**, wie oft *take the question* und *add the question* benutzt wurden, und **Opened**, wie oft ein Chat überhaupt durch eine seiner sechs Türen geöffnet wurde. Jeder Abschnitt zählt sich selbst zusammen, denn die beiden Protokolle schreiben verschiedene Programme und dürfen nicht nach Augenmaß addiert werden. Unter beiden Abschnitten zählt eine zweite Linie und eine weitere Zeile die beiden Protokolle zusammen, denn „was hat mich das gekostet“ ist eine Frage, gleich welche Hälfte des Produkts es ausgegeben hat. Im Rundenprotokoll erscheinen Chat-Züge weiterhin als *conversation*-Zeilen.",
    why: "Eine Prüfrunde gibt in jeder Runde echtes Geld aus, und die Frage „was hat mich das diesen Monat gekostet“ lässt sich aus einer Sitzungsdatei nicht beantworten: Sitzungen werden im Lauf der Runden überschrieben und halten je einen Branch.",
    setup: "Für die Token gibt es nichts einzurichten: der Server hängt pro Prüfer eine Zeile an `usage.jsonl` in seinem Datenverzeichnis, und dieser Abschnitt liest sie.\n\nFür GELD gibt es eine Sache, und nur Sie können sie liefern: **was dieser Anbieter pro Million Token verlangt, hinein und hinaus**, in seiner eigenen Zeile. Dieses Produkt liefert absichtlich keine Preistabelle mit — eine mitgelieferte ist falsch für jeden mit Pauschalabo, falsch beim ersten Preiswechsel eines Anbieters, und in beiden Fällen still falsch. Tragen Sie einen Satz ein, erscheint das Geld dieses Anbieters; lassen Sie ihn leer, bleibt ein Strich.",
    usage: "**Ein gescheiterter Prüfer wird mitgezählt.** Ein Lauf, der neunzig Sekunden verbrannt und nichts geantwortet hat, ist genau das, was eine Ausgabenaufzeichnung nicht verstecken darf, also trägt jede Zeile ihr Ergebnis und die Zahl der Fehlschläge steht neben den Token.\n\n**Die Tilde trägt Bedeutung.** `$0.42` ist, was ein Anbieter berechnet hat; `~$0.42` ist, was Ihr eigener Satz ergibt. Claude meldet seine Kosten, Codex und Antigravity melden nur Token — bei diesen beiden also eine Tilde oder ein Strich, nie eine nackte Zahl. Die Summe hält die Hälften aus demselben Grund getrennt: sie liest sich als `$0.18 + ~$0.31`, statt eine Tatsache zu einer Rechnung zu addieren und das Ergebnis als eines von beiden auszugeben.\n\nUnter einem Dollar wird Geld mit vier Dezimalstellen gezeigt. Eine Runde, die acht Hundertstel Cent gekostet hat, ist eine echte Zahl, und sie auf `$0.00` zu runden sagt, dass die Ansicht nicht zählt.",
    whatCanGoWrong: "Token werden pro Anbieter gezählt, weil eine einzige Regel für mindestens einen falsch wäre: Codex faltet gecachte Token IN die Eingabezahl, Claude meldet sie DANEBEN, und bei Antigravity liegen Denk-Token innerhalb der Ausgabe. Claude meldet denselben Lauf zudem zweimal mit verschiedenen Zahlen; der aggregierte wird genommen.",
  },
  "questions-waiting": {
    title: "Eine Frage, die auf Sie wartet",
    whatItIs: "Braucht das Gate einen Menschen, erscheint oben im Panel eine Karte mit der Frage und den weiterhin blockierenden Befunden. Ein Dialog öffnet sich, in der Statusleiste erscheint ein Eintrag, und das Symbol in der Titelzeile wird grün.",
    why: "Hinter dieser Frage steht eine BLOCKIERTE Runde. Eine Benachrichtigung, die man verpassen kann, taugt dafür nicht — daher drei Oberflächen, und das Schließen des Dialogs verliert nichts.",
    setup: "Für den gewöhnlichen Fall nichts einzustellen: der Server schreibt die Frage als Datei in das Verzeichnis, das die Erweiterung ohnehin beobachtet, und keine der beiden Hälften öffnet einen Port. Ein Fall braucht doch eine Einstellung. Eine Runde, die in einer ANDEREN Installation läuft — etwa eine Claude-Code-Sitzung in WSL —, schreibt ihre Frage in das Datenverzeichnis JENER Installation, und ein Fenster, das nur sein eigenes beobachtet, zeigt sie nie, während die Runde blockiert. `coai.alsoWatchDataDirectories` benennt die anderen Verzeichnisse: Fragen aus einer anderen Installation erscheinen neben den eigenen, und die Antwort wird neben die Frage geschrieben — dorthin, wo der fragende Server hinsieht. Geteilt werden nur die Fragen; keine Datenbank wird über die Grenze hinweg geöffnet. Aus einem Windows-Fenster muss ein WSL-Verzeichnis so benannt werden, wie Windows es erreicht: `\\\\wsl.localhost\\<distro>\\home\\<user>\\.local\\share\\coai-mcp` — ein Pfad, der mit `/` beginnt, wird mit Begründung abgelehnt, statt ein Verzeichnis zu beobachten, das niemand gewählt hat.",
    usage: "Antworten können Sie im Panel, im Dialog oder aus der Statusleiste — es ist dieselbe Handlung. Die Antwort geht an die fragende KI, übersetzt in die Sprache, in der sie gefragt hat, und Ihre eigenen Worte bleiben daneben stehen.",
    whatCanGoWrong: "Auch das Verdikt `call_human` erzeugt so eine Karte, damit ein Gate mit aufgebrauchten Runden Sie erreicht, selbst wenn die KI schweigt. Das war nicht immer so: früher war das Verdikt nur eine Anweisung an die KI, und ein Mensch konnte den ganzen Tag auf das Panel sehen, ohne zu erfahren, dass er gerufen wurde.",
  },
  "prompts-in-full": {
    title: "Die Prompts, vollständig",
    whatItIs: "Der vollständige Text jedes Prompts, den dieses Produkt an einen Prüfer sendet — die vier universellen, die acht engen Linsen und der Konventionsdurchgang. Hier ist nichts umschrieben; das liest das Modell.",
    why: "Eine Prüfung, die man nicht nachprüfen kann, muss man glauben. Genau zu wissen, was gefragt wurde, erlaubt zu beurteilen, ob eine Antwort fair war — und ob ein Befund, dem Sie widersprechen, von einem schlechten Modell oder einer schlechten Frage kam.",
    setup: "Nichts einzurichten. Was unten steht, wird von einem Test gegen die eigenen Prompt-Dateien des Servers geprüft, kann also nicht von dem abweichen, was wirklich läuft.\n\nDer Prompt **conventions** steht für sich und nicht unter einer Rolle, weil er keine Linse auf die Frage einer Rolle ist: es ist eine andere Frage, die alle drei Code-Rollen in Runde eins stellen. Die Regeln kommen mit ihm — die eigenen `CLAUDE.md`, `AGENTS.md`, `GEMINI.md` und `.claude/rules` des Projekts, gelesen aus dem Worktree des geprüften Commits und wörtlich zitiert, bis 40 KB, wobei alles Ausgelassene benannt und nicht still verworfen wird.",
    usage: "Jeder Prompt endet mit derselben Disziplin: ein Befund muss eine konkrete Situation und das falsche Ergebnis nennen, das sie erzeugt; vier Arten von Nicht-Befunden sind benannt und verboten; und es steht ausdrücklich da, dass eine leere Befundliste eine gültige Antwort ist — ein Prüfer, dem man sagt, immer etwas zu finden, wird immer etwas finden.\n\nJeden davon können Sie überschreiben: legen Sie eine Datei mit dem Namen des Prompts in `prompts/` im Datenverzeichnis des Servers ab, und sie gewinnt, solange sie existiert. Löschen Sie sie, gilt wieder der ausgelieferte Text.",
    whatCanGoWrong: "Eine Überschreibung wird nicht geprüft. Ein Prompt, der das Befundschema nicht verlangt, erzeugt Antworten, die nicht geparst werden können, und die Runde meldet diesen Prüfer als nicht parsbar — mit seiner Rohantwort auf der Platte, damit Sie sehen, wonach Sie gefragt haben.",
  },
  "the-help-page": {
    title: "Diese Seite: Suche, Sprache und Textgröße",
    whatItIs: "Das gelbe ? in der Titelzeile öffnet diese Hilfe. Die Liste zeigt jeden Artikel mit seiner ersten Zeile; das Feld oben durchsucht alle; die Auswahl wechselt die Sprache; die ±-Schaltflächen ändern die Textgröße, und das Paar daneben den Textton — heller, oder matter und wärmer.",
    why: "Ein Einstellungspanel mit sechzehn Elementen braucht einen Ort, der sagt, was jedes tut — ein Tooltip taugt dafür nicht. Die Textgröße steht hier, weil Sehkraft nichts ist, worüber man streitet: fünf Schritte in jede Richtung sind etwa ×1,6 hinauf oder hinunter.",
    setup: "Nichts einzustellen. Der Sprachschalter schreibt `coai.helpLanguage` und gilt nur für diese Seiten — es ist nicht die Sprache, in der Ihre Reviewer gefragt werden, die steht im Abschnitt **Language**. Die ±-Schaltflächen schreiben `coai.uiScale` und `coai.textTone`; die Null des Tons ist die Farbe Ihres eigenen Themes, ein unberührter Regler ändert also nichts. Beides sind echte Einstellungen und werden auf Ihre anderen Maschinen synchronisiert.",
    usage: "Gesucht wird in den Überschriften UND im vollen Text jedes Artikels in der gezeigten Sprache — ein Wort, das Ihnen aus einem Absatz in Erinnerung blieb, findet also den Artikel, in dem es stand. Escape schließt einen Artikel zurück zur Liste, und Back behält das Getippte.\n\nEin nicht übersetzter Artikel zeigt Englisch mit sichtbarem Hinweis, keine leere Seite.",
    whatCanGoWrong: "Dass eine Übersetzung dem Englischen hinterherhinkt, ist normal und wird gekennzeichnet. Was nicht passieren kann, ist ein fehlender Artikel: ein Abdeckungstest lässt den Build scheitern, wenn zu einem Befehl oder einer Einstellung nichts geschrieben steht. Genau deshalb kann diese Seite nicht still zur Beschreibung eines Produkts werden, das es nicht mehr gibt.",
  },
  "the-protocol": {
    title: "Unter der Haube: das Protokoll, dem Ihre KI folgt",
    whatItIs: "Neun Werkzeuge in fester Reihenfolge. `open` öffnet eine Sitzung für Repository und Branch. `review_plan` schickt den Plan an alle Reviewer. `resolve` hält für JEDEN Befund fest, ob er angenommen oder abgelehnt wurde. `review_code` tut dasselbe für das Diff, mit vier Rollen je Hersteller. `review_document` ist das andere Tor — ein DOKUMENT statt eines Diffs, ohne Planrunde davor und mit einer eigenen Sitzung je Dokument. `providers` zeigt den Zustand, `status` bringt ein wieder aufgenommenes Gespräch zurück in den Kontext, `ask_human` eskaliert zu Ihnen. `consult` ist das neunte und das einzige, das nichts abriegelt: ein festgefahrener Assistent fragt das Modell eines anderen Herstellers zu Ihrem Arbeitsbaum, wie er gerade ist, und bekommt eine Antwort statt eines Urteils.",
    why: "Die Reihenfolge hält durch Verweigerung, nicht durch gutes Benehmen: `review_code` verweigert, solange keine Planrunde *proceed* erreicht hat — eine Stufe zu überspringen ist also unmöglich und nicht bloß „nicht empfohlen“.",
    setup: "Nichts einzustellen — das steuert Ihre KI. Die Reihenfolge sagt ihr genau der Absatz, den Sie ins Repository eingefügt haben.",
    usage: "Eine Ablehnung verlangt eine Begründung, und die Begründung bleibt erhalten: ein abgelehnter Befund zählt in weiteren Runden nicht, bis ein Reviewer ihn mit einem neuen Argument erneut vorbringt. Genau das hindert die Schleife daran, eine Entscheidung neu aufzurollen, die Sie schon getroffen haben.",
    whatCanGoWrong: "Eine Runde, in der NIEMAND geantwortet hat, geht nie durch. Ein leeres Ergebnis ist das Fehlen von Belegen, nicht der Beleg für ein Fehlen: das Gate ruft stattdessen einen Menschen. Das ist der einzige Fall, in dem „keine Befunde“ nicht „freigegeben“ heißen darf.",
  },
  "where-reviewers-run": {
    title: "Unter der Haube: wo ein Reviewer wirklich läuft",
    whatItIs: "Die Code-Stufe gibt der Runde EIN git-worktree, festgenagelt auf den Commit des Branches, nur lesbar. Die Plan-Stufe gibt jedem Reviewer stattdessen ein LEERES Verzeichnis.",
    why: "Gibt man einer agentischen CLI ein Repository und einen Plan, der Dateien nennt, geht sie diese lesen. Gemessen: acht Minuten und immer noch am Laufen — bei einem Dokument von fünfzehn Kilobyte. Die Aufgabe dort ist, das DOKUMENT zu beurteilen; das Repository braucht die Code-Stufe.",
    setup: "Nichts einzustellen. Die Worktrees liegen im Datenverzeichnis des Servers und werden beim Öffnen einer Sitzung aufgeräumt, sodass eine abgebrochene Runde nichts hinterlässt.",
    usage: "Was das leere Verzeichnis kostet, im Klartext: ein Plan-Reviewer kann nicht prüfen, ob ein Verweis der Form `file.cs:line` im Plan echt ist. Diese Prüfung stand im Plan-Prompt ohnehin nie, und sie mit der zehnfachen Laufzeit zu erkaufen ist der falsche Tausch für ein Gate, an dem ein Mensch wartet.",
    whatCanGoWrong: "Der einzige Wiederholungsversuch eines Reviewers läuft aus demselben Grund ebenfalls im leeren Verzeichnis: die Reparatur bittet um die Antwort im Schema, nicht um neue Recherche. Genau das erneute Aushändigen eines Checkouts kostete in einer von drei Code-Runden einen Reviewer.",
  },
  "when-a-reviewer-fails": {
    title: "Unter der Haube: was passiert, wenn ein Reviewer scheitert",
    whatItIs: "Sechs benannte Ausgänge und niemals eine stille Null: geantwortet, ins Timeout gelaufen, mit Fehlercode beendet, ins Ratenlimit gelaufen, nicht startbar, oder mit etwas geantwortet, das sich nicht parsen lässt. Eine Runde, die mit vier von sechs Reviewern durchlief, sagt genau das — mit Namen.",
    why: "Ein Panel, das nicht reviewt hat, ist kein Panel, das zugestimmt hat. Jede unvollständige Runde meldet sich als unvollständig, und der Reviewer-Satz im Panel nennt, wer scheiterte und warum.",
    setup: "Nichts einzustellen. Ein Reviewer im Ratenlimit wird nach einer Pause genau einmal wiederholt — es sei denn, der Hersteller hat gesagt, das Limit gelte für den TAG, und das heilt keine Wiederholung.",
    usage: "Eine Absage trägt die eigenen Worte der CLI, nach Inhalt gewählt und nicht nach Position: die erste Zeile, die einen Fehler ankündigt, vorbei an Stack-Frames und Versionsbannern. Für fünf bekannte Absagen — geschlossene CLI, nicht vertrautes Verzeichnis, fehlende Binärdatei für die Plattform — wird gesagt, WAS ZU TUN IST, statt was gedruckt wurde.",
    whatCanGoWrong: "Eine Antwort, die sich nicht parsen ließ, wird unter `unparseable/` im Datenverzeichnis gespeichert, und die Absage nennt die Datei. Das kam daher, dass dieselbe Antwort, von Hand nachgestellt, sauber durchlief — die Meldung nannte also ein Symptom, das sich nicht untersuchen ließ.",
  },
  "settings-and-the-server": {
    title: "Unter der Haube: wie eine Einstellung den Server erreicht",
    whatItIs: "Das Panel schreibt Ihre Einstellungen in eine Datei im Datenverzeichnis des Servers, und der Server liest diese Datei neu, sobald sie sich ändert.",
    why: "Früher erreichten Einstellungen den Server nur im eingefügten Konfigurationsblock, und jede Änderung einer Schwelle wurde zur Prozedur: Block kopieren, Client-Konfiguration finden, einfügen, neu starten. Und sie galten nur beim Start — ein Bruch, der von beiden Seiten unsichtbar war, weil das Panel sofort speichert und das auch so sagt.",
    setup: "Nichts einzustellen. Eine Änderung im Panel gilt ab der NÄCHSTEN Runde: kein Neustart, kein erneutes Einfügen.",
    usage: "Eine Variable in der Konfiguration des Assistenten schlägt die Datei weiterhin: sie ist spezifischer als eine Datei, die jedes Fenster überschreiben kann.\n\nDas Panel schreibt nur, was von den Voreinstellungen ABWEICHT — eine Einstellung auf ihre Voreinstellung zurückzusetzen entfernt sie also aus der Datei, statt sie festzuschreiben.",
    whatCanGoWrong: "Eine halb geschriebene Datei lässt die letzte funktionierende Konfiguration stehen. Ein zerrissener Lesevorgang mit leerer Herstellerliste hätte jeden Reviewer scheitern lassen und wäre von einem Panel gemeldet worden, das mit sich selbst einig ist.\n\nGetrennte Einstellungen je Seite: auf einem Rechner können mehrere Arbeitsumgebungen liegen - ein lokales Fenster und eine oder mehrere WSL-Distributionen - und VS Code gibt ihnen DIESELBE Einstellungsdatei. Wird der Schalter eingeschaltet, behält jede Seite ihre eigenen Werte, angelegt aus dem, was sie in diesem Moment hatte, sodass sich bis zur ersten Änderung nichts ändert. Für eine Person, die auf einem Rechner für zwei Firmen arbeitet, heißt das: ein anderer Proxy, ein anderer CLI-Pfad und ein anderer Tresorschlüssel je Seite. Textgröße und Hilfesprache bleiben gemeinsam - sie gehören Ihnen und nicht der Arbeit.",
  },
  "the-audit-log": {
    title: "Unter der Haube: das Audit-Log",
    whatItIs: "Eine Logdatei pro Serverlauf, unter `logs/<Tag>/` in demselben Ordner, in dem der Server alles andere hält — siehe *Wo Ihre Daten liegen*. Darin die Besetzung jeder Runde, Start und Antwort jedes Reviewers mit Tokens und Geld, jede Absage als Warnung mit Grund, und jeder Befund mit seiner Herkunft.",
    why: "Die Rundenzusammenfassung ist bewusst ein Satz, und ein Satz beantwortet nicht „warum ist dieser Reviewer gescheitert“. Diese Frage kam an einem echten Gate zweimal auf, und beide Male gab es nichts zu antworten.",
    setup: "Nichts einzustellen. Die Stufen kommen aus der Konfiguration statt aus Aufrufstellen, und je Lauf entsteht eine neue Datei — nicht je Tag, weil fast immer gefragt wird, was JENER Lauf getan hat.",
    usage: "Auf Debug-Stufe wird die exakte Kommandozeile jedes Reviewers geschrieben — das ist der Unterschied zwischen „wissen, dass der Hersteller gefragt wurde“ und „den Befehl ins Terminal einfügen und dieselbe Absage sehen“.",
    whatCanGoWrong: "Das Log ist der einzige Ort, an dem manches überhaupt festgehalten wird. Es rotiert nicht und wird nicht beschnitten: ein Jahr dichter Arbeit ist ein Ordner kleiner Dateien — kein Problem, aber aufräumen müssen Sie ihn.",
  },
  "where-your-data-lives": {
    title: "Wo Ihre Daten liegen, und wie Sie sie behalten",
    whatItIs: "Ein Ordner enthält alles, woran sich dieses Produkt erinnert: die Runden-Datenbank, die Sitzungen, Ihre Chats mit ihren Bildern, die von Ihnen bearbeiteten Prompts, das Ausgabenbuch und die Prüfaufzeichnungen. Standardmäßig ist das `%LOCALAPPDATA%\\coai-mcp` unter Windows und `~/.local/share/coai-mcp` sonst. Der Abschnitt *MCP server* der Leiste nennt den Ordner, den genau dieses Fenster liest.",
    why: "Der Standardordner liegt auf der Systemplatte, und die Systemplatte ist das, was formatiert wird. Zeigen Sie stattdessen auf ein Netzlaufwerk oder ein NAS, und Ihre Historie überlebt das Betriebssystem darüber: neu installieren, den MCP-Server erneut einrichten, denselben Ordner wählen — und jede Runde, die Sie je gefahren haben, ist noch da. Denselben Ordner können sich ein Windows-Fenster und ein WSL-Fenster derselben Maschine teilen.",
    setup: "Die Installation des MCP-Servers fragt, beim ersten Mal auf jeder Seite einer Maschine: den Standardordner behalten oder einen wählen. Einen Ordner zu wählen, in dem bereits eine Datenbank liegt, ÜBERNIMMT sie — genau darum geht es, und so nimmt eine neu aufgesetzte Maschine ihre eigene Historie wieder auf. Sie können es auch selbst in den Einstellungen setzen: `coai.dataDirectory` für den Ordner und `coai.dataSide` für den Namen dieser Installation darin. Beide werden pro Seite der Maschine gehalten, denn dasselbe NAS ist `Z:\\coai` in einem Windows-Fenster und `/mnt/z/coai` in einem WSL-Fenster. Danach trägt der Abschnitt *MCP server* der Leiste eine Schaltfläche **Change where your data lives**, und die Befehlspalette hat denselben Eintrag.",
    usage: "Ein Server erfährt den Ordner nur aus dem Client-Eintrag, der ihn startet; deshalb trägt der Block, den *Install the MCP server…* in Ihre Zwischenablage legt, ihn bereits mit: einmal einfügen, den Assistenten neu starten — und beide Hälften lesen dieselbe Stelle.\n\nGeben Sie einer Seite einen Namen, wenn sich zwei Installationen einen Ordner teilen; jede hält darin ihre eigene Datenbank, ihre Sitzungen und ihre Anmeldungen. Lassen Sie ihn leer, wenn nur diese Installation den Ordner benutzt.",
    whatCanGoWrong: "Leiste und Server können am Ende verschiedene Ordner lesen — genau das bedeutet eine leere Rundenliste, während Ihr Assistent sagt, er prüfe gerade. Der Abschnitt nennt den Ordner, den DIESES FENSTER liest, und reicht die zwei Zeilen heraus, mit denen ein Server ihm zustimmt.\n\nEin Seitenname darf Kleinbuchstaben, Ziffern, Punkt, Bindestrich und Unterstrich enthalten. Alles andere wird zurückgewiesen statt stillschweigend ignoriert, und der Server startet damit nicht: ein Rückfall auf den gemeinsamen Ordner setzte jede Installation auf eine Datenbank — das Gegenteil dessen, wofür eine Seite da ist.\n\nEinen Ordner umzuziehen, in dem schon etwas liegt, ist eine Kopie, die Sie machen, während nichts läuft, und es ist mehr als die Datenbank: die Sitzungen, die Chats und ihre Bücher, die bearbeiteten Prompts, das Ausgabenbuch und die Prüfaufzeichnungen und die Logs ziehen mit um — mit einer Ausnahme: haben Sie dieser Installation einen Seitennamen gegeben, schreibt der Server seine Logs in den Ordner ÜBER der Seite, sodass ein Umzug sie nicht erreicht und das vorher sagt. Lassen Sie die flüchtigen Worktrees und die Anmelde-Token zurück — ein Token gehört der Seite, die ihn erworben hat.\n\n**Move your data to another folder** erledigt diese Kopie für Sie: es verweigert, solange noch etwas schreibt, verweigert einen Ordner, der bereits eine eigene Historie hält, kopiert, und liest den neuen Ordner dann zurück und vergleicht ihn mit dem alten, bevor es dieses Fenster dorthin zeigen lässt. Es löscht nichts. **Delete the old data folder** ist eine eigene Aktion und bleibt verweigert, bis ein Umzug aufgegangen ist — eine Kopie, die nicht aufging, ist eine, für die der alte Ordner die einzige Stelle sein kann, an der etwas noch existiert.",
  },
};
